// Conceptual Saga approach using Spring Events for eventual consistency
@Service
public class OrderService {
    @Transactional
    public void createOrder(Order order) {
        orderRepository.save(order);
        // Publish event to trigger downstream services asynchronously
        eventPublisher.publishEvent(new OrderCreatedEvent(order.getId()));
    }
}

// Compensating transaction logic in the Inventory service
@EventListener
public void handleOrderCreated(OrderCreatedEvent event) {
    try {
        inventoryService.reserve(event.getOrderId());
    } catch (Exception e) {
        // If reservation fails, trigger compensation to revert the Order status
        eventPublisher.publishEvent(new InventoryFailedEvent(event.getOrderId()));
    }
}
